#!/usr/bin/env node
'use strict';
/**
 * generate-script-registry.js (v9.0.368)
 * Scans all project scripts and generates scripts/_registry.json:
 * every tool with its path, size, first meaningful description line
 * (from its header comment) and last git modification date.
 * Solves the recurring "which script does X?" problem.
 *
 * Usage: node .github/scripts/generate-script-registry.js
 */
const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');

const ROOT = path.join(__dirname, '..', '..');
const SCAN_DIRS = ['scripts', 'tools', '.github/scripts'];
const OUT = path.join(ROOT, 'scripts', '_registry.json');

function describe(file) {
  try {
    const head = fs.readFileSync(file, 'utf8').slice(0, 2000);
    // first comment block line that looks like a description
    const lines = head.split('\n');
    for (const raw of lines) {
      const l = raw.replace(/^\s*(\/\/|#|\*|\/\*+)\s?/, '').trim();
      if (l.length > 15 && !/^(use strict|@param|@returns?|===|---|\*\/|eslint|require\(|!|#!|\/usr\/bin)/.test(l)) {
        return l.slice(0, 140);
      }
    }
  } catch { /* unreadable */ }
  return '';
}

function lastModified(rel) {
  try {
    return execSync(`git log -1 --format=%cs -- "${rel}"`, { cwd: ROOT, encoding: 'utf8' }).trim();
  } catch { return null; }
}

function main() {
  const entries = [];
  for (const dir of SCAN_DIRS) {
    const base = path.join(ROOT, dir);
    if (!fs.existsSync(base)) {continue;}
    const walk = (d) => {
      for (const e of fs.readdirSync(d, { withFileTypes: true })) {
        const p = path.join(d, e.name);
        if (e.isDirectory()) {
          if (['node_modules', 'legacy', 'legacy-archived', 'quarantine', 'duplicates'].includes(e.name)) {continue;}
          walk(p);
        } else if (/\.(js|cjs|mjs|ps1|sh)$/.test(e.name)) {
          const rel = path.relative(ROOT, p).replace(/\\/g, '/');
          entries.push({
            path: rel,
            dir,
            description: describe(p),
            lastModified: lastModified(rel),
          });
        }
      }
    };
    walk(base);
  }
  entries.sort((a, b) => a.path.localeCompare(b.path));
  const registry = {
    generated: new Date().toISOString(),
    count: entries.length,
    note: 'Auto-generated by .github/scripts/generate-script-registry.js — do not edit by hand.',
    scripts: entries,
  };
  fs.writeFileSync(OUT, JSON.stringify(registry, null, 1));
  console.log(`[registry] ${entries.length} scripts recensés → ${path.relative(ROOT, OUT)}`);
}

main();
